before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <limits.h>
_Static_assert(CHAR_BIT == 8, "format requires 8-bit bytes");

int main(void) {
    unsigned char bytes[2] = {1, 2};
    unsigned long value = ((unsigned long)bytes[0] << 8) | bytes[1];
    printf("%lu\n", value);
    return 0;
}
```

